-- COSMOS sites from the EVE University wiki (flat model: beacon +
-- first-pocket NPC pack; agents stand at their own site beacon).
-- +migrate Up
CREATE TABLE IF NOT EXISTS cosmosSites (
  siteID int(10) unsigned NOT NULL,
  siteName varchar(120) NOT NULL,
  systemID int(10) unsigned NOT NULL,
  factionID int(10) unsigned NOT NULL DEFAULT 0,
  corporationID int(10) unsigned NOT NULL DEFAULT 0,
  siteType varchar(20) NOT NULL DEFAULT '',
  rating varchar(10) NOT NULL DEFAULT '',
  shipLimit varchar(60) NOT NULL DEFAULT '',
  beaconTypeID int(10) unsigned NOT NULL DEFAULT 19706,
  ox bigint NOT NULL DEFAULT 0, oy bigint NOT NULL DEFAULT 0, oz bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (siteID), KEY systemID (systemID)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cosmosSiteNpcs (
  siteID int(10) unsigned NOT NULL,
  pocket tinyint(3) unsigned NOT NULL,
  typeID int(10) unsigned NOT NULL,
  qty smallint(5) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (siteID, pocket, typeID)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cosmosAgentSites (
  agentID int(10) unsigned NOT NULL,
  siteID int(10) unsigned NOT NULL,
  PRIMARY KEY (agentID), KEY siteID (siteID)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cosmosSiteDrops (
  siteID int(10) unsigned NOT NULL,
  pocket tinyint(3) unsigned NOT NULL,
  typeID int(10) unsigned NOT NULL,
  qty smallint(5) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (siteID, pocket, typeID)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cosmosSiteGates (
  siteID int(10) unsigned NOT NULL,
  pocket tinyint(3) unsigned NOT NULL,
  passkeyTypeID int(10) unsigned NOT NULL,
  passkeyQty smallint(5) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (siteID, pocket)
) ENGINE=InnoDB;
DELETE FROM cosmosSiteDrops;
DELETE FROM cosmosSiteGates;
DELETE FROM cosmosSiteNpcs;
DELETE FROM cosmosAgentSites;
DELETE FROM cosmosSites;

